from pathlib import Pathfrom src.output import save_copydef test_save_copy_creates_file(tmp_path, monkeypatch):    output_dir = tmp_path / "outputs"    monkeypatch.setattr(        "src.output.OUTPUT_DIR",        output_dir    )    image_path = Path("images/test.jpg")    copy = "Este es un copy de prueba."    output_path = save_copy(copy, image_path)    assert output_path.exists()    assert output_path.name == "test_copy.txt"    assert output_path.read_text(encoding="utf-8") == copydef test_save_copy_creates_output_directory(tmp_path, monkeypatch):    output_dir = tmp_path / "outputs"    monkeypatch.setattr(        "src.output.OUTPUT_DIR",        output_dir    )    image_path = Path("images/producto.png")    save_copy("Copy de prueba", image_path)    assert output_dir.exists()